// Build enriched context for RCA Agent
const trigger    = $('Execute Workflow Trigger').first().json;
const recentAlarms = $('Fetch Recent Alarms (Same Device)').all().map(i => i.json).filter(a => a.alarm_type);
const deviceInfo   = $('Fetch Device Info').first()?.json || {};

const context = {
  current_alarm: {
    alarm_id:        trigger.alarm_id,
    incident_id:     trigger.incident_id,
    device_name:     trigger.device_name,
    alarm_type:      trigger.alarm_type,
    severity:        trigger.severity,
    interface_name:  trigger.interface_name || 'N/A',
    description:     trigger.description,
    alarm_timestamp: trigger.alarm_timestamp,
  },
  device_info: {
    device_type:     deviceInfo.device_type || 'Unknown',
    vendor:          deviceInfo.vendor || 'Unknown',
    model:           deviceInfo.model || 'Unknown',
    location:        deviceInfo.location || 'Unknown',
    network_role:    deviceInfo.network_role || 'Unknown',
    ip_address:      deviceInfo.ip_address || 'N/A',
    management_ip:   deviceInfo.management_ip || 'N/A',
  },
  recent_alarms_same_device: recentAlarms.slice(0, 5).map(a => ({
    alarm_type: a.alarm_type,
    severity:   a.severity,
    timestamp:  a.alarm_timestamp,
    status:     a.processing_status,
  })),
  agent_started_at: new Date().toISOString(),
};

return [{ json: { context } }];

