// Parse and validate RCA Agent output
const raw         = $input.first().json;
const agentOutput = typeof raw.text === 'string' ? raw.text : (typeof raw.content === 'string' ? raw.content : '');
// chainLlm runs with onError=continue, so a failed LLM call arrives here as { error }
const llmError    = raw.error ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error)) : null;
const context     = $('Build RCA Context').first().json.context;

let parsed;
try {
  if (llmError) throw new Error('LLM call failed: ' + llmError);
  const cleaned = agentOutput.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    probable_root_cause:     'Unable to determine — analysis failed',
    confidence:              0.1,
    root_cause_category:     'Unknown',
    supporting_evidence:     [],
    alternative_causes:      [],
    timeline_analysis:       'Analysis failed: ' + e.message,
    correlation_with_recent_alarms: 'N/A',
    requires_physical_inspection: true,
    estimated_repair_time_hours: null,
    parse_error: e.message,
  };
}

// Ensure arrays
if (!Array.isArray(parsed.supporting_evidence)) parsed.supporting_evidence = [];
if (!Array.isArray(parsed.alternative_causes))  parsed.alternative_causes = [];

const validCategories = ['Hardware Failure','Fiber Cut','Configuration Error','Software Bug','Environmental','External Attack','Human Error','Unknown'];
if (!validCategories.includes(parsed.root_cause_category)) parsed.root_cause_category = 'Unknown';

return [{
  json: {
    ...parsed,
    alarm_id:     context.current_alarm.alarm_id,
    incident_id:  context.current_alarm.incident_id,
    agent_name:   'root_cause_analysis',
    completed_at: new Date().toISOString(),
  }
}];
